import { ATTACHMENT_ERROR_CODES } from '@pulse-chat/shared';

import { ApiException } from '../../../common/errors/api.exception.js';
import { STORAGE_KEY_PATTERN } from './generate-storage-key.js';

/** Rejects keys that were not generated by this application. */
export function assertSafeStorageKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) {
    throw new ApiException(
      ATTACHMENT_ERROR_CODES.INVALID_STORAGE_KEY,
      'Storage key is invalid.',
      400,
    );
  }
}
